<?php
require dirname(__DIR__).'/includes/bootstrap.php';$admin=require_admin();$errors=[];
$platforms=['NES','Game Boy','Game Boy Color','Super Nintendo','Nintendo 64','PlayStation 1'];
$tags=$pdo->query('SELECT id,name FROM tags ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$title=trim((string)($_POST['title']??''));$platform=(string)($_POST['platform']??'');$description=trim((string)($_POST['description_markdown']??''));$manualUrl=trim((string)($_POST['manual_url']??''));$selectedTags=array_values(array_unique(array_map('intval',$_POST['tags']??[])));
 if($title===''||mb_strlen($title)>160)$errors[]='Le titre est obligatoire (160 caractères maximum).';if(!in_array($platform,$platforms,true))$errors[]='Plateforme invalide.';if(count($selectedTags)>16)$errors[]='Choisis seize tags maximum.';if($manualUrl!==''&&!filter_var($manualUrl,FILTER_VALIDATE_URL))$errors[]='Le lien du manuel doit être une URL valide.';if($manualUrl!==''&&!preg_match('#^https?://#i',$manualUrl))$errors[]='Le lien du manuel doit commencer par http:// ou https://.';
 if(empty($_FILES['rom']['name']))$errors[]='Une ROM est obligatoire.';
 if(!$errors){$romPath=$thumbPath=$manualPath=null;try{$romPath=safe_upload($_FILES['rom'],'rom');$thumbPath=safe_upload($_FILES['thumbnail']??['error'=>UPLOAD_ERR_NO_FILE],'thumbnail');$manualPath=safe_upload($_FILES['manual']??['error'=>UPLOAD_ERR_NO_FILE],'manual');if(!$manualPath)$manualPath=null;$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO games(title,platform,description_markdown,rom_path,rom_original_name,thumbnail_path,manual_path,manual_url,created_by) VALUES(:t,:p,:d,:r,:o,:th,:m,:mu,:u)');$s->execute(['t'=>$title,'p'=>$platform,'d'=>$description,'r'=>$romPath,'o'=>basename((string)$_FILES['rom']['name']),'th'=>$thumbPath,'m'=>$manualPath,'mu'=>$manualUrl?:null,'u'=>$admin['id']]);$gameId=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO game_tags(game_id,tag_id) VALUES(:g,:t)');foreach($selectedTags as $tid){$check=$pdo->prepare('SELECT id FROM tags WHERE id=:id');$check->execute(['id'=>$tid]);if($check->fetch())$ins->execute(['g'=>$gameId,'t'=>$tid]);}$pdo->commit();flash('Jeu ajouté à la bibliothèque.','success');redirect('admin/games.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();foreach([$romPath,$thumbPath,$manualPath] as $path)if($path&&is_file(dirname(__DIR__).'/'.$path))@unlink(dirname(__DIR__).'/'.$path);error_log('Admin game upload: '.$e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Impossible d’enregistrer le jeu. Vérifie les limites d’upload et la base de données.';}}
}
$games=$pdo->query('SELECT id,title,platform,created_at FROM games ORDER BY id DESC')->fetchAll();$pageTitle='Administration des jeux';require dirname(__DIR__).'/includes/header.php';?>
<section class="panel"><h1>Administration des jeux</h1><div class="admin-nav"><a class="btn" href="<?=e(url('admin/games.php'))?>">Ajouter / jeux</a><a class="btn" href="<?=e(url('admin/users.php'))?>">Gérer les membres</a><a class="btn" href="<?=e(url('index.php'))?>">Voir le site</a></div><?php foreach($errors as $err): ?><div class="flash error"><?=e($err)?></div><?php endforeach; ?><h2>Ajouter un jeu</h2><p>Les fichiers sont enregistrés sur le serveur; SQL ne conserve que leur chemin et leurs métadonnées. N’envoie que des fichiers que tu as le droit d’héberger.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label for="title">Titre</label><input id="title" name="title" maxlength="160" required></div><div class="field"><label for="platform">Plateforme</label><select id="platform" name="platform" required><?php foreach($platforms as $p): ?><option value="<?=e($p)?>"><?=e($p)?></option><?php endforeach; ?></select></div><div class="field"><label for="rom">ROM (64 Mo max) <span class="help" tabindex="0">?<span>Formats pris en charge : NES, GB/GBC, SFC/SMC, N64 et ISO/BIN/CUE. Limite applicative : 64 Mo (le serveur PHP doit aussi autoriser cette taille). La prise en charge par l’émulateur est distincte du stockage.</span></span></label><input id="rom" name="rom" type="file" required accept=".nes,.gb,.gbc,.sfc,.smc,.z64,.n64,.v64,.iso,.bin,.cue"></div><div class="field"><label for="thumbnail">Miniature (5 Mo maximum)</label><input id="thumbnail" name="thumbnail" type="file" accept=".jpg,.jpeg,.png,.webp"></div><div class="field"><label>Tags (16 maximum)</label><div><?php foreach($tags as $tag): ?><label style="display:inline-block;margin:5px"><input type="checkbox" name="tags[]" value="<?=(int)$tag['id']?>"> <?=e($tag['name'])?></label><?php endforeach; ?></div><p class="muted">Les tags standards et les catégories de difficulté sont disponibles ici. Plusieurs tags peuvent être associés à un jeu.</p></div><div class="field"><label for="manual">Manuel PDF (10 Mo maximum)</label><input id="manual" name="manual" type="file" accept="application/pdf,.pdf"></div><div class="field"><label for="manual_url">Ou lien HTTP(S) vers le manuel</label><input id="manual_url" name="manual_url" type="url" maxlength="2048" placeholder="https://..."></div><div class="field"><label for="description_markdown">Description (Markdown simplifié) <span class="help" tabindex="0">?<span>Prend en charge # titres, **gras**, *italique*, `code` et [liens](https://exemple.com). Le HTML brut est échappé.</span></span></label><textarea id="description_markdown" name="description_markdown" placeholder="# Présentation&#10;**Genre :** aventure&#10;Description du jeu..."></textarea></div><button class="btn" type="submit">Ajouter le jeu</button></form></section>
<section class="panel"><h2>Jeux existants</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Titre</th><th>Plateforme</th><th>Ajouté le</th></tr></thead><tbody><?php foreach($games as $g): ?><tr><td><?=(int)$g['id']?></td><td><a href="<?=e(url('game.php?id='.(int)$g['id']))?>"><?=e($g['title'])?></a></td><td><?=e($g['platform'])?></td><td><?=e($g['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div><p class="muted">La suppression/modification des jeux n’est pas encore exposée dans cette première version; elle est à ajouter avant une utilisation publique étendue.</p></section>
